 [card("l4-1-c1","Each part has a different job.",[k+": "+v+" — "+desc+"." for k,v,desc in components],q0["id"]),card("l4-1-c2","The subject is the whole class being discussed.",["All library books are loanable items: library books is the subject."],q1["id"]),card("l4-1-c3","A logical term can contain several words.",["School gardens and cultivated areas each function as a term."],{**q3,"id":"l4-1-boundaries-card","level":1})],
